From 2e07a22ad2b99c4fec15e99446c1adaaff3e8b67 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:51:45 +0100
Subject: [PATCH] applets/appmenu: keep the last window's menu while the panel
 has focus

Opening a panel popup such as the launcher or the system tray took focus
from the app, so the Global Menu emptied. Keep showing the last app's
menus while a panel or one of its popups has focus, but not the desktop.

BUG: 481686
---
 applets/appmenu/appmenumodel.cpp | 14 +++++++++++++-
 applets/appmenu/appmenumodel.h   |  1 +
 2 files changed, 14 insertions(+), 1 deletion(-)

diff --git a/applets/appmenu/appmenumodel.cpp b/applets/appmenu/appmenumodel.cpp
index e91d858062..974a533892 100644
--- a/applets/appmenu/appmenumodel.cpp
+++ b/applets/appmenu/appmenumodel.cpp
@@ -60,6 +60,7 @@ AppMenuModel::AppMenuModel(QObject *parent)
     connect(m_tasksModel, &TaskManager::TasksModel::virtualDesktopChanged, this, &AppMenuModel::onActiveWindowChanged);
     connect(m_tasksModel, &TaskManager::TasksModel::countChanged, this, &AppMenuModel::onActiveWindowChanged);
     connect(m_tasksModel, &TaskManager::TasksModel::screenGeometryChanged, this, &AppMenuModel::screenGeometryChanged);
+    connect(qGuiApp, &QGuiApplication::focusWindowChanged, this, &AppMenuModel::onActiveWindowChanged);

     connect(this, &AppMenuModel::modelNeedsUpdate, this, [this] {
         if (!m_updatePending) {
@@ -219,7 +220,18 @@ void AppMenuModel::onActiveWindowChanged()
         return;
     }

-    const QModelIndex activeTaskIndex = m_tasksModel->activeTask();
+    QModelIndex activeTaskIndex = m_tasksModel->activeTask();
+    if (activeTaskIndex.isValid()) {
+        m_lastActiveTask = activeTaskIndex;
+    } else if (const QWindow *focusWindow = QGuiApplication::focusWindow()) {
+        // Keep showing the last window's menu while a panel or one of its popups has focus, but not the desktop
+        if (focusWindow->inherits("DesktopView")) {
+            m_lastActiveTask = QPersistentModelIndex();
+        } else {
+            activeTaskIndex = m_lastActiveTask;
+        }
+    }
+
     const QString objectPath = m_tasksModel->data(activeTaskIndex, TaskManager::AbstractTasksModel::ApplicationMenuObjectPath).toString();
     const QString serviceName = m_tasksModel->data(activeTaskIndex, TaskManager::AbstractTasksModel::ApplicationMenuServiceName).toString();
     updateApplicationMenu(serviceName, objectPath);
diff --git a/applets/appmenu/appmenumodel.h b/applets/appmenu/appmenumodel.h
index ba4a64eaa1..cb8fc9c94f 100644
--- a/applets/appmenu/appmenumodel.h
+++ b/applets/appmenu/appmenumodel.h
@@ -90,6 +90,7 @@ private:

     Plasma::Types::ItemStatus m_containmentStatus = Plasma::Types::PassiveStatus;
     TaskManager::TasksModel *m_tasksModel;
+    QPersistentModelIndex m_lastActiveTask;

     std::unique_ptr<QMenu> m_searchMenu;
     QPointer<QMenu> m_menu;
